ding\",\n      \"kind\": \"function\",\n      \"signature\": \"finding(#{ name, severity, flow_id, detail, tags })\",\n      \"description\": \"Record a security finding; severity is info | low | medium | high | critical.\"\n    },\n    {\n      \"name\": \"ok\",\n      \"kind\": \"function\",\n      \"signature\": \"ok(resp)\",\n      \"description\": \"Prelude helper: wrap resp as a successful short-circuit response.\"\n    },\n    {\n      \"name\": \"contains_ci\",\n      \"kind\": \"function\",\n      \"signature\": \"contains_ci(hay, needle)\",\n      \"description\": \"Prelude helper: case-insensitive substring check.\"\n    },\n    {\n      \"name\": \"json\",\n      \"kind\": \"function\",\n      \"signature\": \"json(m)\",\n      \"description\": \"Prelude helper: encode the map m as a JSON string.\"\n    }\n  ],\n  \"dsl\": [\n    {\n      \"name\": \"b64_encode\",\n      \"kind\": \"function\",\n      \"signature\": \"b64_encode(s)\",\n      \"description\": \"Base64-encode s (standard alphabet, `=` padding).\"\n    },\n    {\n      \"name\": \"b64_decode\",\n      \"kind\": \"function\",\n      \"signature\": \"b64_decode(s)\",\n      \"description\": \"Base64-decode s; errors on invalid base64 or non-UTF-8 bytes.\"\n    },\n    {\n      \"name\": \"url_encode\",\n      \"kind\": \"function\",\n      \"signature\": \"url_encode(s)\",\n      \"description\": \"Percent-encode s for use in a URL (RFC 3986 unreserved set).\"\n    },\n    {\n      \"name\": \"hex_encode\",\n      \"kind\": \"function\",\n      \"signature\": \"hex_encode(s)\",\n      \"description\": \"Lowercase-hex-encode the UTF-8 bytes of s.\"\n    },\n    {\n      \"name\": \"sha256\",\n      \"kind\": \"function\",\n      \"signature\": \"sha256(s)\",\n      \"description\": \"SHA-256 digest of s, as lowercase hex.\"\n    },\n    {\n      \"name\": \"md5\",\n      \"kind\": \"function\",\n      \"signature\": \"md5(s)\",\n      \"description\": \"MD5 digest of s, as lowercase hex (legacy, non-secure).\"\n    },\n    {\n      \"name\": \"rand_text_alpha\",\n      \"kind\": \"function\",\n      \"signature\": \"rand_text_alpha(n)\",\n      \"description\": \"A random string of n ASCII letters.\"\n    },\n    {\n      \"name\": \"rand_int\",\n      \"kind\": \"function\",\n      \"signature\": \"rand_int(a, b)\",\n      \"description\": \"A random integer in the inclusive range [a, b]; errors when a > b.\"\n    },\n    {\n      \"name\": \"regex_match\",\n      \"kind\": \"function\",\n      \"signature\": \"regex_match(pat, s)\",\n      \"description\": \"True when pattern pat matches anywhere in s; errors on an invalid pattern.\"\n    },\n    {\n      \"name\": \"regex_extract\",\n      \"kind\": \"function\",\n      \"signature\": \"regex_extract(pat, s, group)\",\n      \"description\": \"The text of capture group of pat's first match in s (\\\"\\\" if none); errors on an invalid pattern.\"\n    }\n  ],\n  \"reg\": [\n    {\n      \"name\": \"reg.add_command\",\n      \"kind\": \"method\",\n      \"signature\": \"reg.add_command(name, help, |args| { ... })\",\n      \"description\": \"Register a script command, callable from `load(reg)`. `reg` is the registration handle passed to the load hook.\"\n    },\n    {\n      \"name\": \"reg.add_option\",\n      \"kind\": \"method\",\n      \"signature\": \"reg.add_option(name, default, help)\",\n      \"description\": \"Register a configurable option, callable from `load(reg)`; read it back later with `option(name)`.\"\n    }\n  ],\n  \"vars\": [\n    {\n      \"name\": \"vars.get\",\n      \"kind\": \"method\",\n      \"signature\": \"vars.get(name) -> value\",\n      \"description\": \"Read a PoC run variable by name. `vars` is the per-step handle a PoC `script:` step runs against.\"\n    },\n    {\n      \"name\": \"vars.set\",\n      \"kind\": \"method\",\n      \"signature\": \"vars.set(name, value)\",\n      \"description\": \"Set a PoC run variable, visible to later steps.\"\n    }\n  ],\n  \"denied\": [\n    {\n      \"name\": \"denied.capability\",\n      \"kind\": \"property\",\n      \"signature\": \"denied.capability -> string\",\n      \"description\": \"The capability that was denied. `denied` is the token a scope-/SSRF-gated host call returns when it is refused.\"\n    },\n    {\n      \"name\": \"denied.host\",\n      \"kind\": \"property\",\n      \"signature\": \"denied.host -> string\",\n      \"description\": \"The host the denied call targeted.\"\n    },\n    {\n      \"name\": \"denied.reason\",\n      \"kind\": \"property\",\n      \"signature\": \"denied.reason -> string\",\n      \"description\": \"Why the call was denied.\"\n    }\n  ]\n}\n"

    static let pocYAMLSchemaJSON = "{\n  \"_comment\": \"PoC YAML key tree for schema-aware completion + hover (UI spec §1.1). Content mirrors docs/superpowers/specs/2026-10-27-aitmproxy-poc-language-design.md §'Document structure', §'Step types', §'Matcher / extractor DSL', §'Success / assertion model' and its four worked examples. Node = { type, description, required?, enum?, keys?, items?, one_of_keys?, $ref? }. `keys` is the child key map of a `map`; `items` is the element node of a `list`; `$ref` is `#/$defs/<name>`. Completion walks the YAML nesting: key position -> the enclosing node's `keys`; after `key:` -> that node's `enum` (or true/false for `boolean`). If the builder's validation poc-schema ships, regenerate this from it.\",\n  \"type\": \"map\",\n  \"description\": \"A PoC document.\",\n  \"keys\": {\n    \"id\": { \"type\": \"string\", \"required\": true, \"description\": \"Unique PoC identifier (no spaces).\" },\n    \"info\": {\n      \"type\": \"map\",\n      \"required\": true,\n      \"description\": \"Identification metadata for the PoC.\",\n      \"keys\": {\n        \"name\": { \"type\": \"string\", \"description\": \"Human title.\" },\n        \"author\": { \"type\": \"string\", \"description\": \"Optional author.\" },\n        \"severity\": {\n          \"type\": \"enum\",\n          \"enum\": [\"info\", \"low\", \"medium\", \"high\", \"critical\"],\n          \"description\": \"How serious the finding is; maps to Severity.\"\n        },\n        \"description\": { \"type\": \"string\", \"description\": \"What the finding is (no fix prose).\" },\n        \"reference\": { \"type\": \"list\", \"description\": \"URLs, CVE or CWE references.\", \"items\": { \"type\": \"string\", \"description\": \"One reference.\" } },\n        \"tags\": { \"type\": \"list\", \"description\": \"Tags for selection and reporting.\", \"items\": { \"type\": \"string\", \"description\": \"One tag.\" } },\n        \"cwe\": { \"type\": \"string\", \"description\": \"Optional CWE identifier, e.g. CWE-79.\" },\n        \"metadata\": { \"type\": \"map\", \"description\": \"Arbitrary key: value metadata.\" }\n      }\n    },\n    \"variables\": {\n      \"type\": \"list\",\n      \"description\": \"Reusable {{placeholders}} with optional defaults.\",\n      \"items\": {\n        \"type\": \"map\",\n        \"description\": \"One variable definition.\",\n        \"keys\": {\n          \"name\": { \"type\": \"string\", \"description\": \"The variable name, referenced as {{name}}.\" },\n          \"default\": { \"type\": \"any\", \"description\": \"Default value; may be a DSL expression wrapped in {{ }}, evaluated once at run start.\" },\n          \"description\": { \"type\": \"string\", \"description\": \"What the variable is for.\" },\n          \"required\": { \"type\": \"boolean\", \"description\": \"Whether the caller must supply a value (default false).\" }\n        }\n      }\n    },\n    \"steps\": {\n      \"type\": \"list\",\n      \"required\": true,\n      \"description\": \"Ordered steps; each entry has exactly one step key.\",\n      \"items\": {\n        \"type\": \"map\",\n        \"description\": \"One step.\",\n        \"one_of_keys\": [\"http\", \"browser\", \"extract\", \"script\", \"l4\"],\n        \"keys\": {\n          \"http\": {\n            \"type\": \"map\",\n            \"description\": \"Send an HTTP request through the proxy's guarded client.\",\n            \"keys\": {\n              \"method\": { \"type\": \"string\", \"description\": \"HTTP method: GET, POST, ...\" },\n              \"url\": { \"type\": \"string\", \"description\": \"Full URL (templated).\" },\n              \"path\": { \"type\": \"string\", \"description\": \"Path relative to {{BaseURL}} (templated).\" },\n              \"headers\": { \"type\": \"map\", \"description\": \"Request headers (templated).\" },\n              \"body\": { \"type\": \"string\", \"description\": \"Request body (templated); use raw for full control.\" },\n              \"raw\": { \"type\": \"string\", \"description\": \"Full raw HTTP text with placeholders (nuclei RAW mode).\" },\n              \"extract\": { \"type\": \"list\", \"description\": \"Post-response extractors.\", \"items\": { \"$ref\": \"#/$defs/extractor\" } },\n              \"matchers\": { \"type\": \"list\", \"description\": \"Per-step matchers.\", \"items\": { \"$ref\": \"#/$defs/matcher\" } },\n              \"matchers-condition\": {\n                \"type\": \"enum\",\n                \"enum\": [\"and\", \"or\"],\n                \"description\": \"How this step's matchers combine.\"\n              }\n            }\n          },\n          \"browser\": {\n            \"type\": \"map\",\n            \"description\": \"Drive the embedded browser with one action.\",\n            \"keys\": {\n              \"action\": {\n                \"type\": \"enum\",\n                \"enum\": [\"navigate\", \"click\", \"type\", \"eval\", \"screenshot\"],\n                \"description\": \"Which browser action to run.\"\n              },\n              \"url\": { \"type\": \"string\", \"description\": \"Page to load (navigate); SSRF-guarded.\" },\n              \"target\": { \"type\": \"string\", \"description\": \"Selector or x,y to click (click).\" },\n              \"selector\": { \"type\": \"string\", \"description\": \"Element to type into (type).\" },\n              \"text\": { \"type\": \"string\", \"description\": \"Text to type (type).\" },\n              \"expr\": { \"type\": \"string\", \"description\": \"JavaScript to run; bind or assert its value (eval).\" },\n              \"label\": { \"type\": \"string\", \"description\": \"Artifact label for the PNG (screenshot).\" }\n            }\n          },\n          \"extract\": { \"$ref\": \"#/$defs/extractor\" },\n          \"script\": {\n            \"type\": \"map\",\n            \"description\": \"Rhai escape hatch using the plugin-system Rhai API, plus vars.get/vars.set.\",\n            \"keys\": {\n              \"name\": { \"type\": \"string\", \"description\": \"Optional label; success can reference the step's verdict by this name.\" },\n              \"script\": { \"type\": \"string\", \"description\": \"Rhai source; may `return pass` or `return fail`.\" }\n            }\n          },\n          \"l4\": {\n            \"type\": \"map\",\n            \"description\": \"Run a native L4 verb and assert on the received `packet` (scapy-style, human-readable). `op: send_recv` injects a stimulus and binds the reply as the `packet` source (e.g. `field: tcp.flags`).\",\n            \"keys\": {\n              \"op\": {\n                \"type\": \"enum\",\n                \"enum\": [\"craft\", \"inject\", \"send_recv\"],\n                \"description\": \"Allowed values for `op` in a `l4:` step.\"\n              }\n            },\n            \"sources\": [\"packet\"]\n          }\n        }\n      }\n    },\n    \"success\": {\n      \"type\": \"map\",\n      \"required\": true,\n      \"description\": \"What 'triggered' means: an assertion tree evaluated after all steps. A bare matcher, or a list of matchers, is also allowed.\",\n      \"keys\": {\n        \"all\": { \"type\": \"list\", \"description\": \"True when every assertion holds.\", \"items\": { \"$ref\": \"#/$defs/matcher\" } },\n        \"any\": { \"type\": \"list\", \"description\": \"True when at least one assertion holds.\", \"items\": { \"$ref\": \"#/$defs/matcher\" } },\n        \"not\": { \"$ref\": \"#/$defs/matcher\" }\n      }\n    }\n  },\n  \"$defs\": {\n    \"matcher\": {\n      \"type\": \"map\",\n      \"description\": \"A matcher or assertion over a response, the page, or a step's verdict.\",\n      \"keys\": {\n        \"type\": {\n          \"type\": \"enum\",\n          \"enum\": [\"status\", \"word\", \"regex\", \"size\", \"binary\", \"dsl\", \"browser-eval\"],\n          \"description\": \"The matcher kind.\"\n        },\n        \"status\": { \"type\": \"integer\", \"description\": \"Expected status code (status).\" },\n        \"word\": { \"type\": \"string\", \"description\": \"Literal word to find (word).\" },\n        \"regex\": { \"type\": \"string\", \"description\": \"Pattern to match (regex).\" },\n        \"size\": { \"type\": \"integer\", \"description\": \"Expected content length (size).\" },\n        \"binary\": { \"type\": \"string\", \"description\": \"Hex byte signature (binary).\" },\n        \"dsl\": { \"type\": \"string\", \"description\": \"DSL expression over status_code, body, all_headers, content_length and extracted vars (dsl).\" },\n        \"expr\": { \"type\": \"string\", \"description\": \"JavaScript to evaluate in the page (browser-eval).\" },\n        \"equals\": { \"type\": \"string\", \"description\": \"Expected value of expr (browser-eval).\" },\n        \"encoding\": { \"type\": \"enum\", \"enum\": [\"hex\"], \"description\": \"Value encoding for word.\" },\n        \"part\": {\n          \"type\": \"enum\",\n          \"enum\": [\"body\", \"header\", \"all\"],\n          \"description\": \"Which part of the response to match (default body).\"\n        },\n        \"condition\": {\n          \"type\": \"enum\",\n          \"enum\": [\"and\", \"or\"],\n          \"description\": \"How a matcher's own values combine.\"\n        },\n        \"negative\": { \"type\": \"boolean\", \"description\": \"Invert the match.\" },\n        \"internal\": { \"type\": \"boolean\", \"description\": \"Precondition only; not printed.\" },\n        \"name\": { \"type\": \"string\", \"description\": \"Label for the matcher, referenceable from success.\" }\n      }\n    },\n    \"extractor\": {\n      \"type\": \"map\",\n      \"description\": \"Extracts a value from a response or the page; a named extractor binds a variable.\",\n      \"keys\": {\n        \"name\": { \"type\": \"string\", \"description\": \"Binds a variable for later steps.\" },\n        \"type\": {\n          \"type\": \"enum\",\n          \"enum\": [\"regex\", \"json\", \"kval\", \"dsl\", \"browser-eval\"],\n          \"description\": \"The extractor kind.\"\n        },\n        \"from\": {\n          \"type\": \"enum\",\n          \"enum\": [\"body\", \"header\", \"all\"],\n          \"description\": \"Which part of the response to extract from.\"\n        },\n        \"regex\": { \"type\": \"string\", \"description\": \"Pattern with capture groups (regex).\" },\n        \"group\": { \"type\": \"integer\", \"description\": \"Capture group to take (regex).\" },\n        \"json\": { \"type\": \"string\", \"description\": \"JSONPath or jq expression (json).\" },\n        \"kval\": { \"type\": \"string\", \"description\": \"Header or cookie key, dashes as underscores (kval).\" },\n        \"expr\": { \"type\": \"string\", \"description\": \"Expression to evaluate (dsl, browser-eval).\" },\n        \"internal\": { \"type\": \"boolean\", \"description\": \"Pass between steps without printing.\" }\n      }\n    },\n    \"protocol_step\": {\n      \"type\": \"map\",\n      \"description\": \"A protocol namespace's native `<ns>:` step (extensibility seam). Its body keys are the namespace's verb vocabulary — host-fn names from the Rhai `<ns>.*` vocabulary, or the one-shot subset of them that fits a single assertion step (e.g. l4's wire verbs) — and a sibling `extract:` reads a field from one of the step's named sources. Concrete `<ns>` step entries under steps[].items.keys are generated from each protocol's NamespaceCatalog; this is the shared shape they take. The l4 namespace is the first consumer (Task 6): see steps[].items.keys.l4.\",\n      \"keys\": {\n        \"op\": { \"type\": \"string\", \"description\": \"The verb to run; one of the namespace's host-fn names.\" }\n      }\n    },\n    \"protocol_extractor\": {\n      \"type\": \"map\",\n      \"description\": \"A `<ns>:` step's sibling extractor: reads `field` from a named source the step produced (e.g. `type: packet, field: tcp.flags`).\",\n      \"keys\": {\n        \"name\": { \"type\": \"string\", \"description\": \"Binds a variable for later steps and success.\" },\n        \"type\": { \"type\": \"string\", \"description\": \"The source name the step produced (e.g. packet, echo).\" },\n        \"field\": { \"type\": \"string\", \"description\": \"Dotted field path into the named source (e.g. tcp.flags).\" },\n        \"internal\": { \"type\": \"boolean\", \"description\": \"Pass between steps without printing.\" }\n      }\n    }\n  }\n}\n"
}
